from pathlib import Path
import json
w=Path('/tmp/claim-audit-zugd_bv7')
r=json.loads((w/'input/report-ledger.json').read_text())
s=json.loads((w/'input/source-ledger.json').read_text())
def ev(a):
 for p,d in s.items():
  if a in d: return {'path':p,'anchor':a,'quote':d[a]}
 raise ValueError(a)
def pr(t,relation,target):return {'module':'Audit','theorem':'Audit.'+t,'relation':relation,'target':target}
f=[]
def add(i,q,anchors,rules,reason,state,arg,formal,proof,limits,recommendation,assumptions=None):
 k=f'PA-{i:02d}'
 f.append({'claim_id':k,'report_anchor':k,'report_quote':r[k],'question':q,'evidence':[ev(a) for a in anchors],'rules':rules,'assumptions':assumptions if assumptions is not None else ['The supplied register is accepted as documentary fact within R01 coverage, and its exact event labels and UTC timestamps are faithfully transcribed; authenticity is not independently established.'],'reasoning':[str(j+1)+'. '+x for j,x in enumerate(reason)],'semantic_state':state,'argument_status':arg,'formal_status':formal,'proofs':proof,'limits':limits,'recommendation':recommendation})
add(1,'Did C-101 satisfy the P-17 revision 3 standard path at its recorded 2028-04-10 09:00 UTC start, and was its explicitly granted duty-manager approval strictly earlier?', ['P01','P02','R01','R02'],['P02 requires a duty-manager grant strictly before start. P01 makes the standard path sufficient for authorized start.'],['R02 records a duty-manager grant at 08:40 and actual start at 09:00 on the same UTC date.','The grant precedes the start by 20 minutes: offsets 520 < 540.','Both the stated ordering and standard-path conclusion follow; there is no missing conjunct in P02.'],'supported','sufficient','proved',[pr('claim01','supports','Audit.standard Audit.c101 = true ∧ (520 : Int) < 540')],['This is compliance under fictional P-17 revision 3 only, not an assessment of other policies or prudence.'],'Retain the conclusion and cite R02 and P02.')
add(2,'Did C-102 have a standard duty-manager grant strictly before its 2028-04-10 10:15 UTC start, and can its 10:00 request count as that grant?', ['P02','R01','R03'],['P02 explicitly separates submitting or acknowledging a request from granting approval. R01 permits treating the explicit covered none as negative evidence.'],['R03 records the 10:00 request, actual start at 10:15, and standard approval: none.','A request being earlier than start does not make it an approval; the event-kind requirement fails.','The covered explicit absence refutes a pre-start standard grant independently of the request/grant distinction. Both assertions in the report fail.'],'refuted','invalid_inference','refuted',[pr('claim02','refutes','Audit.standard Audit.c102 = false ∧ Audit.c102Request ≠ Audit.EventKind.approval')],['Failure of the standard path alone does not determine overall authorization; the emergency path is assessed separately in PA-03 and PA-08.'],'Replace with: C-102 had a pre-start request but no standard duty-manager approval; assess the emergency path separately.')
add(3,'Did C-102 meet every P03 condition, including a countersignature at or after actual start and at or before exactly 24 hours later?', ['P01','P03','R01','R03'],['P03 requires qualifying active incident AND pre-start duty-officer declaration AND duty-manager countersignature in the inclusive interval [start, start + 24 hours].'],['R03 records qualifying incident I-62 active at start, not merely an emergency declaration.','The duty-officer declaration at 10:05 on April 10 is strictly before the recorded 10:15 start.','The duty-manager countersignature at 10:15 on April 11 is exactly 1440 minutes after start; it meets both inclusive endpoints.','All P03 conditions hold. Lack of a standard grant does not defeat this permitted alternative.'],'supported','sufficient','proved',[pr('claim03','supports','Audit.emergency Audit.c102 = true ∧ (2055 - 615 : Int) = 1440')],['The result uses the explicit inclusive deadline and exact-minute UTC convention; it does not support prudence.'],'Retain the conclusion and explicitly identify the exactly-24-hour inclusive boundary.')
add(4,'Was C-103 duty-manager approval strictly before its recorded 2028-04-10 11:30 UTC start, as required for P02?', ['P02','R01','R04'],['P02 explicitly excludes approval at exactly the starting timestamp; before means strict less-than.'],['R04 gives both approval and actual start as 2028-04-10 11:30 UTC.','Both offsets are 690. Equality cannot satisfy 690 < 690.','The stated strict ordering is false and the standard-path conclusion fails. This is an actual equal-time counterexample, not missing evidence.'],'refuted','invalid_inference','refuted',[pr('claim04','refutes','Audit.standard Audit.c103 = false ∧ ¬ ((690 : Int) < 690)')],['This finding targets the report\'s standard-path assertion. Other paths require their own conditions.'],'Correct the finding to say that simultaneous approval and start failed the strict P02 requirement.')
add(5,'Did C-104 actually start and satisfy neither of the only two authorization paths under P-17 revision 3 at its 2028-04-10 13:20 UTC start?', ['P01','P02','P03','R01','R05'],['P01 exhaustively defines authorized start as standard OR emergency. P02 and P03 specify their required conditions. R01 gives covered none entries negative evidential force.'],['R05 positively records actual start at 13:20, so the claim is not vacuous.','R05 explicitly records no duty-manager approval, ruling out P02.','It also records no qualifying incident, no emergency declaration and no countersignature, ruling out P03.','Because P01 lists no third path, the recorded start was unauthorized under this policy.'],'supported','sufficient','proved',[pr('claim05','supports','Audit.c104.start = 800 ∧ Audit.standard Audit.c104 = false ∧ Audit.emergency Audit.c104 = false ∧ Audit.authorized Audit.c104 = false')],['Exhaustiveness is confined to P-17 revision 3 and the recorded period; no external legal consequence follows.'],'Retain with both failed paths and R01 coverage stated explicitly.')
add(6,'Does the supplied corpus establish absence of any C-105 standard duty-manager approval before the proposed 2028-04-11 09:00 UTC time?', ['P02','R01','H01','H02','A01','A02'],['R01 completeness explicitly excludes C-105. H01 completeness concerns package contents only. H02 cannot confirm or deny approval events. Missing transferred records do not entail event absence.'],['No C-105 standard approval is supplied, but neither is a covered explicit negative approval entry.','H01 proves only that the package lacks the register; H02 says records were not transferred and neither confirms nor denies approval.','A01 and A02 concern whether the operation began, not approval; neither supplies the missing approval premise.','An approval before the proposed time and no such approval are both compatible with the recorded package absence. The auxiliary two-assignment witness shows why the absence inference fails.','The negative event claim remains undetermined; the audit has not established that approval existed.'],'undetermined','insufficient_support','auxiliary',[pr('claim06Countermodels','auxiliary','Audit.possibleApproved.packageContainsRegister = false ∧ Audit.possibleUnapproved.packageContainsRegister = false ∧ Audit.possibleApproved.approvalBeforeProposedStart = true ∧ Audit.possibleUnapproved.approvalBeforeProposedStart = false')],['The model proves a failure of entailment from package absence, not the truth or falsity of the actual C-105 approval claim. Actual start is also disputed, but this claim uses the proposed time and does not require resolving it.'],'Obtain a complete external North Quay approval record or a reliable explicit event-level denial; meanwhile state that pre-start approval is unverified.',['H01-H02 are interpreted at their explicit documentary scope; neither possible-world assignment is asserted as actual history.'])
add(7,'What evidence supports and denies that the same proposed operation C-105 began on 2028-04-11 at 09:00 UTC, and can the dispute be resolved?', ['A01','A02','H02','P04'],['Attributed witness assertions remain distinct from settled occurrence facts. P04 supplies no conflict-resolution rule; H02 identifies the same proposed operation and certifies no start timestamp.'],['Mira Vale explicitly affirms the 09:00 start and says she was present.','Leon Reed explicitly denies any start that day before his 12:10 note, which includes the same 09:00 time.','H02 rules out interpreting them as separate operations; no retraction or priority rule resolves the contradiction.','There is both positive and negative evidence for the exact claim. The auxiliary theorem records both attributions, not contradictory historical truth.'],'both','disputed','auxiliary',[pr('claim07Conflict','auxiliary','Audit.miraAffirmsStart0900 = true ∧ Audit.leonDeniesStart0900 = true')],['Neither witness overrides the other; this audit does not settle whether C-105 actually began. No formal proof of occurrence or nonoccurrence is asserted.'],'Present the conflict explicitly and obtain independent start records or a documented resolution of the witness disagreement.',['The notes are attributed assertions as supplied; no witness reliability preference is assumed.'])
add(8,'Does C-102 lack authorization under P-17 solely because its standard approval is absent, despite the recorded emergency conditions?', ['P01','P02','P03','R01','R03'],['Authorized start is the P01 disjunction of standard and emergency paths. P03 expressly permits start without standard approval. Failure of one disjunct does not imply failure of both.'],['The claim\'s premise is true: R03 explicitly records no standard approval.','The actual same in-scope operation has an active qualifying incident, pre-start declaration and exactly timely countersignature, completing P03.','Consequently C-102 is authorized under the emergency path, contradicting the report\'s nonauthorization conclusion.','C-102 itself is a counterexample to the inference from absent standard approval to unauthorized start; the failure is stronger than a citation gap.'],'refuted','invalid_inference','refuted',[pr('claim08','refutes','Audit.standard Audit.c102 = false ∧ Audit.emergency Audit.c102 = true ∧ Audit.authorized Audit.c102 = true')],['This refutes policy nonauthorization, not any separate qualitative criticism of the emergency decision.'],'State that standard approval was absent but C-102 satisfied the alternative emergency path and was authorized under P-17.')
add(9,'Can the qualitative assertion that C-102 emergency start was prudent be assessed by any operational criterion in the supplied mandate or P-17?', ['P04','P03','R03'],['P04 explicitly supplies no prudence measure and separates authorization from prudence. Policy compliance is not a defined prudence criterion.'],['R03 supports emergency authorization under P03.','Neither the policy nor supplied documents defines prudence or supplies a rule linking authorization to prudence.','The evaluative claim is outside formal assessment under this mandate; neither a prudence proof nor its negation is justified.'],'not_applicable','nonformal','not_attempted',[],['This is a missing operational criterion, not a finding that the start was imprudent or a computation timeout.'],'Keep the assessment explicitly qualitative, or supply an agreed prudence criterion and the evidence required to apply it.',['No extra prudence definition or organizational practice is introduced.'])
add(10,'Does the complete supplied C-105 handoff package inventory exclude an external approval register, independently of whether approval events occurred?', ['H01','H02','R01'],['H01 expressly gives complete package contents and expressly limits completeness to that inventory. Documentary nonmembership does not entail event nonoccurrence.'],['H01 lists the request and two witness notes and explicitly says no external approval register is in the package.','The finite package model therefore contains no external approval register.','H02 corroborates nontransfer, while R01 explains why the local register cannot fill the C-105 coverage gap.','The exact package-content claim is supported. It must not be extended to PA-06\'s historical approval-absence assertion.'],'supported','sufficient','proved',[pr('claim10','supports','Audit.PackageItem.externalApprovalRegister ∉ Audit.handoffPackage')],['The conclusion establishes a supplied attachment absence only; it does not show that an approval register or approval never existed externally.'],'Retain with the explicit package-only scope.',['The H01 package inventory is accepted as complete only for the supplied handoff package.'])
(w/'findings.json').write_text(json.dumps(f,indent=2,ensure_ascii=False)+'\n')
